INSERT INTO "Review" ("user_id", "restaurant_id", "rating", "comment", "created_at", "updated_at")
SELECT u."id", v.restaurant_id, v.rating, v.comment, now() - v.ago::interval,
       CASE WHEN v.edited THEN now() - v.ago::interval + interval '2 days' END
FROM (VALUES
  ('user01@bapit.test', 31, 5, '학교 앞에서 칰폴레맵징거더블다운(세트) 먹을 땐 여기가 최고예요. 맵기가 딱 좋아요.', '49669 minutes', false),
  ('user01@bapit.test', 5, 5, '학교 앞에서 제육덮밥 먹을 땐 여기가 최고예요. 맵기가 딱 좋아요.', '8913 minutes', false),
  ('user02@bapit.test', 36, 5, '탕짜면 진짜 맛있어요! 또 갈 거예요. 면이 쫄깃해요.', '65155 minutes', false),
  ('user02@bapit.test', 14, 5, '학교 앞에서 쉬림프 파스타 포케 먹을 땐 여기가 최고예요. 면이 쫄깃해요.', '63968 minutes', true),
  ('user02@bapit.test', 5, 4, '칼국수 맛있어요. 점심시간엔 조금 기다려요. 면이 쫄깃해요.', '7319 minutes', false),
  ('user02@bapit.test', 37, 5, '학교 앞에서 짬뽕 먹을 땐 여기가 최고예요. 면이 쫄깃해요.', '26091 minutes', false),
  ('user02@bapit.test', 2, 5, '왕새우튀김우동 강추해요. 양도 넉넉해요. 면이 쫄깃해요.', '75756 minutes', false),
  ('user02@bapit.test', 13, 5, '잔치국수 진짜 맛있어요! 또 갈 거예요. 면이 쫄깃해요.', '27674 minutes', false),
  ('user03@bapit.test', 5, 5, '학교 앞에서 떡라면 먹을 땐 여기가 최고예요.', '79582 minutes', false),
